import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { SectionLabel, PillButton, DragNumberField, SegmentedToggle } from './components/UI';
import { TileGrid } from './components/TileGrid';
import { StagedView } from './components/StagedView';
import { SceneView } from './components/SceneView';
import { PatternEditor } from './components/PatternEditor';
import { CopilotHelper } from './components/CopilotHelper';
import { WelcomeModal } from './components/WelcomeModal';
import { removeBackground } from './services/backgroundRemoval';
import { GenerationState, MaterialAsset, MaterialMode, AppMode, PatternState, RepeatType } from './types';

const STYLE_PRESETS = [
  'Modern', 
  'Classical', 
  'Art Deco', 
  'Botanical', 
  'Geometric',
  'Art Nouveau',
  'Mid-Century',
  'Brutalist'
];

const SURFACE_TYPES = [
  'Woven Carpet',
  'Velvet',
  'Ceramic Tile',
  'Wallpaper',
  'Wood Inlay',
  'Marble',
  'Linen',
  'Embossed Leather',
  'Etched Metal'
];

export default function Surface() {
  // App Global State
  const [appMode, setAppMode] = useState<AppMode>('material');
  const [status, setStatus] = useState<GenerationState>('idle');
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [isDescribing, setIsDescribing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<'tile' | 'staged' | 'scene'>('staged');
  const [showWelcome, setShowWelcome] = useState(true);

  // Material Mode State
  const [prompt, setPrompt] = useState('');
  const [inputImage, setInputImage] = useState<{ mediaId: string; base64: string } | null>(null);
  const [materialMode, setMaterialMode] = useState<MaterialMode>('reinterpret');

  // Pattern Mode State
  const [patternState, setPatternState] = useState<PatternState>({
    background: null,
    elements: [],
    drawingBase64: null,
    repeatSettings: {
      type: 'Grid',
      spacing: 0,
      rotation: 0,
      scale: 100
    },
    stylePrompt: '',
    surfaceType: null
  });

  // Assets & View State
  const [tile, setTile] = useState<MaterialAsset | null>(null);
  const [stagedImage, setStagedImage] = useState<MaterialAsset | null>(null);
  const [sceneImage, setSceneImage] = useState<MaterialAsset | null>(null);
  const [surfaceType, setSurfaceType] = useState<'Floor' | 'Wall' | 'Ceiling'>('Floor');
  const [scale, setScale] = useState(50);
  const [density, setDensity] = useState<'1x1' | '2x2' | '4x4' | '8x8'>('1x1');

  // Scene Specific State
  const [sceneStyle, setSceneStyle] = useState('Modern');
  const [sceneLighting, setSceneLighting] = useState('Natural Daylight');
  const [isDesigningScene, setIsDesigningScene] = useState(false);

  useEffect(() => {
    const id = 'surface-styles';
    if (document.getElementById(id)) return;

    // Load Design System Fonts
    const fontLink = document.createElement('link');
    fontLink.rel = 'stylesheet';
    fontLink.href = 'https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600&family=Cormorant+Garamond:wght@300;400;500;600&display=swap';
    document.head.appendChild(fontLink);

    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
      .shimmer { background: linear-gradient(90deg, #1a1a1a 25%, #2a2a2a 50%, #1a1a1a 75%); background-size: 200% 100%; animation: shimmer 2s infinite linear; }

      @keyframes sequence-glow {
        0%, 100% { background: rgba(255,255,255,0.03); box-shadow: none; }
        15%, 45% { background: #EAE4D8; box-shadow: 0 0 15px rgba(234, 228, 216, 0.25); }
      }
      .loading-square { animation: sequence-glow 2.5s infinite ease-in-out; background: rgba(255,255,255,0.03); }

      html, body, #root { 
        margin: 0; padding: 0; width: 100%; height: 100%; 
        background: #0a0a0a; color: #EAE4D8; 
        font-family: 'Poppins', sans-serif; 
        overflow: hidden; 
      }
      .font-display { font-family: 'Cormorant Garamond', serif; }

      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: rgba(255,255,255,0.1) transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 999px; }
      .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }

      input[type=range] { -webkit-appearance: none; background: rgba(255,255,255,0.1); border-radius: 999px; height: 4px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; height: 12px; width: 12px; border-radius: 999px; background: white; cursor: pointer; border: none; }
      @keyframes spin-slow { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      .animate-spin-subtle { animation: spin-slow 2s linear infinite; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleUpload = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (appMode === 'material') {
        setInputImage({ mediaId: media.mediaId, base64: media.base64 });
        setMaterialMode('reinterpret');

        if (!prompt.trim()) {
          setIsDescribing(true);
          try {
            const { text } = await Flow.generate.text(
              "Describe this architectural material in professional detail. Specify the material type, the color palette, and the surface finish (e.g., honed stone, polished metal, deep-pile velvet). Provide only the description text suitable for a texture generator.",
              {
                images: [{ base64: media.base64, mimeType: media.mimeType }],
                systemInstruction: "You are an expert architectural material consultant. Provide concise, descriptive prompts for high-end textures.",
                thinkingLevel: 'low'
              }
            );
            if (text) setPrompt(text.trim());
          } catch (descErr) {
            console.error('Auto-description failed', descErr);
          } finally {
            setIsDescribing(false);
          }
        }
      } else {
        setPatternState({ ...patternState, background: { mediaId: media.mediaId, base64: media.base64, mimeType: media.mimeType } });
      }
    } catch (e) {
      console.error('Upload failed', e);
    }
  };

  const handleEnhancePrompt = async () => {
    if (!prompt.trim() || isEnhancing) return;

    setIsEnhancing(true);
    setError(null);
    try {
      const { text } = await Flow.generate.text(
        `Expand "${prompt}" into a richer, more descriptive architectural material prompt. Focus on specific types, finishes, and textures (e.g. "marble" -> "Carrara marble, soft grey veining, honed matte finish"). Output only the expanded descriptive text, no intro or quotes.`,
        { 
          systemInstruction: 'You are an expert architectural material consultant providing descriptive prompts for high-end interior textures.',
          thinkingLevel: 'low'
        }
      );
      if (text) setPrompt(text.trim());
    } catch (err) {
      console.error('Enhancement failed', err);
      setError('Could not enhance prompt. Try again.');
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleRemoveBackground = async () => {
    if (!patternState.background) return;
    setStatus('removing_bg');
    try {
      const resultBase64 = await removeBackground(patternState.background.base64, patternState.background.mimeType);
      const uploaded = await Flow.upload({
        base64: resultBase64,
        mimeType: 'image/png',
        name: 'Isolated Subject'
      });
      setPatternState({
        ...patternState,
        background: { mediaId: uploaded.mediaId, base64: resultBase64, mimeType: 'image/png' }
      });
    } catch (err) {
      setError('Background removal failed');
    } finally {
      setStatus('idle');
    }
  };

  const makeSeamlessPass = async (rawTile: MaterialAsset, styleLabel: string): Promise<MaterialAsset> => {
    setStatus('healing_seams');
    try {
      const canvas = document.createElement('canvas');
      canvas.width = 1024;
      canvas.height = 1024;
      const ctx = canvas.getContext('2d')!;

      const img = new Image();
      img.src = `data:${rawTile.mimeType};base64,${rawTile.base64}`;
      await new Promise(r => img.onload = r);

      ctx.drawImage(img, 512, 512, 512, 512, 0, 0, 512, 512);
      ctx.drawImage(img, 0, 512, 512, 512, 512, 0, 512, 512);
      ctx.drawImage(img, 512, 0, 512, 512, 0, 512, 512, 512);
      ctx.drawImage(img, 0, 0, 512, 512, 512, 512, 512, 512);

      const offsetBase64 = canvas.toDataURL('image/png').split(',')[1];
      const uploadedOffset = await Flow.upload({
        base64: offsetBase64,
        mimeType: 'image/png',
        name: 'Offset Tile'
      });

      const healPrompt = `Heal and blend the central horizontal and vertical seam lines in this tile. Ensure the pattern flows continuously across the center cross. Match the exact motifs, colors, and textures of the surrounding pattern: ${styleLabel || 'Architectural material'}. Output a perfectly seamless, edge-matching high-resolution tile.`;

      const result = await Flow.generate.image({
        prompt: healPrompt,
        referenceImageMediaIds: [uploadedOffset.mediaId],
        aspectRatio: '1:1',
        modelDisplayName: '🍌 Nano Banana Pro'
      });

      return {
        mediaId: result.mediaId,
        base64: result.base64,
        mimeType: result.mimeType,
        name: rawTile.name
      };
    } catch (err) {
      console.error('Seamless pass failed', err);
      return rawTile;
    }
  };

  const generateTile = async (manualPrompt?: string) => {
    const activePrompt = manualPrompt ?? prompt;
    if (!activePrompt && !inputImage) return;
    setStatus('generating_tile');
    setError(null);
    setView('tile');

    try {
      let fullPrompt = "";
      if (materialMode === 'seamless' && inputImage) {
        fullPrompt = `High resolution perfectly seamless tiling version of the provided material. Maintain all original colors and details exactly. Flat top-down view.`;
      } else {
        fullPrompt = `High resolution seamless texture tile of ${activePrompt || 'the provided material'}. Architectural material, flat view, top-down. ${inputImage ? 'Maintain colors and texture from reference.' : ''}`;
      }

      const result = await Flow.generate.image({
        prompt: fullPrompt,
        referenceImageMediaIds: inputImage ? [inputImage.mediaId] : undefined,
        aspectRatio: '1:1',
        modelDisplayName: '🍌 Nano Banana Pro'
      });

      const rawTileAsset: MaterialAsset = { 
        mediaId: result.mediaId, 
        base64: result.base64, 
        mimeType: result.mimeType, 
        name: activePrompt || 'Generated Material' 
      };

      if (materialMode === 'seamless') {
        const seamlessTile = await makeSeamlessPass(rawTileAsset, activePrompt);
        setTile(seamlessTile);
      } else {
        setTile(rawTileAsset);
      }

      setStatus('idle');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate tile');
      setStatus('idle');
    }
  };

  const handlePresetSelect = (preset: string) => {
    setPrompt(preset);
    setAppMode('material');
    generateTile(preset);
  };

  const generatePattern = async () => {
    setStatus('blending_pattern');
    setError(null);
    setView('tile');

    try {
      const stampCanvas = document.createElement('canvas');
      stampCanvas.width = 1024;
      stampCanvas.height = 1024;
      const sctx = stampCanvas.getContext('2d')!;

      for (const el of patternState.elements) {
        sctx.save();
        sctx.translate((el.x / 100) * 1024, (el.y / 100) * 1024);
        sctx.rotate((el.rotation * Math.PI) / 180);
        const size = (el.size / 100) * 1024;
        sctx.fillStyle = el.color || 'rgba(255,255,255,0.4)';
        sctx.strokeStyle = 'rgba(255,255,255,0.8)';
        sctx.lineWidth = 4;
        if (el.type === 'circle') {
          sctx.beginPath(); sctx.arc(0, 0, size / 2, 0, Math.PI * 2); sctx.fill(); sctx.stroke();
        } else if (el.type === 'square') {
          sctx.fillRect(-size / 2, -size / 2, size, size); sctx.strokeRect(-size / 2, -size / 2, size, size);
        } else if (el.type === 'triangle') {
          sctx.beginPath(); sctx.moveTo(0, -size / 2); sctx.lineTo(size / 2, size / 2); sctx.lineTo(-size / 2, size / 2); sctx.closePath(); sctx.fill(); sctx.stroke();
        } else if (el.type === 'line') {
          sctx.beginPath(); sctx.moveTo(-size / 2, 0); sctx.lineTo(size / 2, 0); sctx.stroke();
        }
        sctx.restore();
      }

      if (patternState.drawingBase64) {
        const drawImg = new Image();
        drawImg.src = patternState.drawingBase64;
        await new Promise(r => drawImg.onload = r);
        sctx.drawImage(drawImg, 0, 0, 1024, 1024);
      }

      const canvas = document.createElement('canvas');
      canvas.width = 1024;
      canvas.height = 1024;
      const ctx = canvas.getContext('2d')!;

      if (patternState.background) {
        const bgImg = new Image();
        bgImg.src = `data:${patternState.background.mimeType};base64,${patternState.background.base64}`;
        await new Promise(r => bgImg.onload = r);
        ctx.drawImage(bgImg, 0, 0, 1024, 1024);
      }

      const { type, spacing, rotation: repeatRotation, scale: repeatScale } = patternState.repeatSettings;
      const gridSize = 2;
      const tileSize = 1024 / gridSize;
      const spacingOffset = (spacing / 100) * tileSize;

      for (let i = 0; i < gridSize; i++) {
        for (let j = 0; j < gridSize; j++) {
          ctx.save();
          let x = i * tileSize + tileSize / 2;
          let y = j * tileSize + tileSize / 2;
          if (type === 'Half-drop' && i % 2 === 1) y += tileSize / 2;
          ctx.translate(x, y);
          ctx.rotate((repeatRotation * Math.PI) / 180);
          let scaleX = repeatScale / 100;
          let scaleY = repeatScale / 100;
          if (type === 'Mirror') {
            if (i % 2 === 1) scaleX *= -1;
            if (j % 2 === 1) scaleY *= -1;
          }
          ctx.scale(scaleX, scaleY);
          ctx.translate(spacingOffset, spacingOffset);
          ctx.drawImage(stampCanvas, -512, -512, 1024, 1024);
          ctx.restore();
        }
      }

      const compositeBase64 = canvas.toDataURL('image/png').split(',')[1];
      const uploaded = await Flow.upload({ base64: compositeBase64, mimeType: 'image/png', name: 'Collage Reference' });

      const materialText = patternState.surfaceType ? `high-fidelity ${patternState.surfaceType} surface` : "wallpaper pattern";

      let materialTexture = "";
      if (patternState.surfaceType === 'Velvet') materialTexture = " with soft light-catching pile and luxurious textile sheen";
      else if (patternState.surfaceType === 'Ceramic Tile') materialTexture = " with a glazed porcelain finish and realistic grout lines";
      else if (patternState.surfaceType === 'Woven Carpet') materialTexture = " with visible woven thread texture and fiber depth";
      else if (patternState.surfaceType === 'Marble') materialTexture = " with natural mineral veining and a polished stone finish";
      else if (patternState.surfaceType === 'Embossed Leather') materialTexture = " with realistic tooled grain and animal hide texture";
      else if (patternState.surfaceType === 'Wood Inlay') materialTexture = " with organic wood grain and artisanal joinery";
      else if (patternState.surfaceType === 'Etched Metal') materialTexture = " with an oxidized or brushed metallic finish and industrial etching";
      else if (patternState.surfaceType === 'Linen') materialTexture = " with a distinctive flax weave and organic fabric slubs";

      const baseInstructions = `An exquisite, high-end interior design ${materialText}${materialTexture}. Reinterpret this rough concept composition into a refined, print-quality artistic surface. Transform the basic marks and shapes into sophisticated, elevated motifs`;
      const styleDirection = patternState.stylePrompt.trim() 
        ? `—specifically in a ${patternState.stylePrompt.trim()} style—`
        : "—such as intricate botanicals, elegant damask, art-deco geometrics, or hand-painted artisanal textures—";

      const generationPrompt = `${baseInstructions}${styleDirection}that best suit the user's intent. Perfectly repeatable, flat top-down view.`;

      const result = await Flow.generate.image({
        prompt: generationPrompt,
        referenceImageMediaIds: [uploaded.mediaId],
        aspectRatio: '1:1',
        modelDisplayName: '🍌 Nano Banana Pro'
      });

      const rawTileAsset: MaterialAsset = { 
        mediaId: result.mediaId, 
        base64: result.base64, 
        mimeType: result.mimeType, 
        name: patternState.stylePrompt || 'Custom Pattern' 
      };

      const seamlessTile = await makeSeamlessPass(rawTileAsset, patternState.stylePrompt);
      setTile(seamlessTile);
      setStatus('idle');
    } catch (err) {
      console.error(err);
      setError('Pattern blending failed');
      setStatus('idle');
    }
  };

  const handleRegenerate = () => {
    if (appMode === 'material') {
      generateTile();
    } else {
      generatePattern();
    }
  };

  const generateStaged = async () => {
    if (!tile) return;
    setStatus('staging');
    setError(null);
    setView('staged');
    try {
      const stagingPrompt = `Wide-angle architectural visualization. Clean, neutral white architectural room shell. A modern ${surfaceType.toLowerCase()} made of ${tile.name}. Luxury minimal architectural interior. Natural side lighting.`;
      const result = await Flow.generate.image({
        prompt: stagingPrompt,
        referenceImageMediaIds: [tile.mediaId],
        aspectRatio: '16:9',
        modelDisplayName: '🍌 Nano Banana Pro'
      });
      setStagedImage({ mediaId: result.mediaId, base64: result.base64, mimeType: result.mimeType, name: `${tile.name} Staged` });
      setStatus('idle');
    } catch (err) {
      setError('Failed to stage material');
      setStatus('idle');
    }
  };

  const generateScene = async () => {
    if (!tile) return;
    setIsDesigningScene(true);
    setError(null);

    try {
      const surfaceDesc = surfaceType === 'Wall' ? 'full feature wall' : surfaceType === 'Floor' ? 'entire floor' : 'full ceiling';
      const scenePrompt = `A cinematic interior photograph of a designed room, built around a single hero material. The ${surfaceDesc} is clad in the supplied texture, preserved exactly — identical colour, relief and pattern, no distortion or recolouring; the texture is the protagonist. Design the rest of the room to harmonise in a ${sceneStyle} direction, restrained and editorial, a few sculptural pieces, palette drawn from the texture. Lighting: ${sceneLighting}. Eye level, 28mm, architectural editorial photography, photoreal. Avoid: distorting, re-tiling or recolouring the texture, clutter, text, watermarks.`;

      const result = await Flow.generate.image({
        prompt: scenePrompt,
        referenceImageMediaIds: [tile.mediaId],
        aspectRatio: '16:9',
        modelDisplayName: '🍌 Nano Banana Pro'
      });

      setSceneImage({
        mediaId: result.mediaId,
        base64: result.base64,
        mimeType: result.mimeType,
        name: `${tile.name} Designed Scene`
      });
    } catch (err) {
      console.error('Scene generation failed', err);
      setError('Failed to design scene');
    } finally {
      setIsDesigningScene(false);
    }
  };

  const downloadAsset = async (asset: MaterialAsset, filename: string) => {
    await Flow.download({ base64: asset.base64, mimeType: asset.mimeType, filename: `${filename.replace(/\s+/g, '_')}.jpg` });
  };

  const updateRepeatSettings = (updates: Partial<PatternState['repeatSettings']>) => {
    setPatternState({
      ...patternState,
      repeatSettings: { ...patternState.repeatSettings, ...updates }
    });
  };

  const updateStylePrompt = (val: string) => {
    setPatternState({ ...patternState, stylePrompt: val });
  };

  const updateSurfaceTypeSelection = (val: string) => {
    setPatternState({ ...patternState, surfaceType: patternState.surfaceType === val ? null : val });
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#0a0a0a]">
      {showWelcome && <WelcomeModal onClose={() => setShowWelcome(false)} />}

      <div className="w-[320px] flex-shrink-0 border-r border-white/10 flex flex-col justify-between py-6 px-5 h-full z-10 bg-[#0a0a0a] relative">
        <div className="flex flex-col gap-8 overflow-y-auto dark-scrollbar pb-12">
          <div className="space-y-1">
            <h1 className="text-sm font-medium tracking-widest uppercase opacity-40">Surface</h1>
            <p className="text-[11px] opacity-30">Creative Material Lab</p>
          </div>

          <div className="flex flex-col gap-2">
            <SectionLabel>Application Mode</SectionLabel>
            <SegmentedToggle 
              value={appMode}
              onChange={(v) => setAppMode(v as AppMode)}
              items={[
                { value: 'material', label: 'Material' },
                { value: 'pattern', label: 'Pattern' }
              ]}
            />
          </div>

          <div className="flex flex-col gap-6">
            {appMode === 'material' ? (
              <div className="flex flex-col gap-5 animate-in fade-in duration-500">
                <div className="flex flex-col gap-3">
                  <SectionLabel>Material Definition</SectionLabel>
                  <div className="relative group/prompt">
                    <textarea
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                      placeholder="Describe your material..."
                      className="w-full h-24 bg-transparent border border-white/10 rounded-xl p-3 pr-10 text-xs focus:outline-none focus:border-white/30 transition-colors resize-none placeholder:opacity-30"
                    />
                    <button 
                      onClick={handleEnhancePrompt}
                      disabled={!prompt.trim() || isEnhancing}
                      className="absolute right-3 top-3 text-white/20 hover:text-white transition-all disabled:opacity-0 pointer-events-auto disabled:pointer-events-none"
                      title="Enhance description"
                    >
                      <span className={`material-symbols-outlined text-[18px] ${isEnhancing ? 'animate-spin-subtle' : ''}`}>
                        {isEnhancing ? 'progress_activity' : 'auto_fix_high'}
                      </span>
                    </button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className="flex-1">
                      <PillButton 
                        variant="outline" 
                        onClick={handleUpload} 
                        disabled={isDescribing}
                        icon={
                          isDescribing ? 
                          <span className="material-symbols-outlined text-[18px] animate-spin-subtle">progress_activity</span> : 
                          <span className="material-symbols-outlined text-[18px]">add_photo_alternate</span>
                        }
                      >
                        {isDescribing ? 'Analyzing...' : (inputImage ? 'Change Image' : 'Add Reference')}
                      </PillButton>
                    </div>
                    {inputImage && (
                      <div className="relative w-[38px] h-[38px] group rounded-xl overflow-hidden border border-white/10">
                        <img src={`data:image/jpeg;base64,${inputImage.base64}`} className="w-full h-full object-cover transition-opacity group-hover:opacity-40" />
                        <button onClick={() => setInputImage(null)} className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="material-symbols-outlined text-[16px]">close</span>
                        </button>
                      </div>
                    )}
                  </div>
                  {inputImage && (
                    <div className="space-y-2">
                      <SectionLabel>Processing Mode</SectionLabel>
                      <SegmentedToggle value={materialMode} onChange={(v) => setMaterialMode(v as MaterialMode)} items={[{ value: 'reinterpret', label: 'Reinterpret' }, { value: 'seamless', label: 'Make Seamless' }]} />
                    </div>
                  )}
                </div>
                <PillButton variant="solid" onClick={() => generateTile()} disabled={status !== 'idle' || (!prompt && !inputImage)} icon={<span className="material-symbols-outlined text-[18px]">texture</span>}>
                  Generate Tile
                </PillButton>
              </div>
            ) : (
              <div className="flex flex-col gap-5 animate-in fade-in duration-500">
                <div className="flex flex-col gap-3">
                  <SectionLabel>Pattern Source</SectionLabel>
                  <div className="flex items-center gap-3">
                    <PillButton variant="outline" onClick={handleUpload} icon={<span className="material-symbols-outlined text-[18px]">upload</span>}>
                      {patternState.background ? 'Replace Image' : 'Upload Image'}
                    </PillButton>
                  </div>
                </div>
                <PatternEditor 
                  state={patternState} 
                  onChange={setPatternState} 
                  onRemoveBackground={handleRemoveBackground}
                  isRemovingBg={status === 'removing_bg'}
                />

                <div className="flex flex-col gap-4 py-4 border-y border-white/5">
                  <SectionLabel>Repeat Layout</SectionLabel>
                  <div className="flex flex-col gap-3">
                    <SegmentedToggle 
                      value={patternState.repeatSettings.type}
                      onChange={(v) => updateRepeatSettings({ type: v as RepeatType })}
                      items={[
                        { value: 'Grid', label: 'Grid' },
                        { value: 'Half-drop', label: 'Drop' },
                        { value: 'Mirror', label: 'Mirror' }
                      ]}
                    />
                    <div className="grid grid-cols-2 gap-2">
