const MAX_HISTORY = 30;

// Color Palette Component
const ColorPalette: React.FC<{ 
  color: string; 
  onChange: (c: string) => void; 
  onClose: () => void 
}> = ({ color, onChange, onClose }) => {
  const paletteRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (paletteRef.current && !paletteRef.current.contains(e.target as Node)) onClose();
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  return (
    <div 
      ref={paletteRef}
      className="absolute bottom-12 right-0 z-[100] w-64 bg-[#1a1a1a] border border-white/10 rounded-2xl shadow-2xl p-4 animate-in fade-in zoom-in-95 duration-150"
    >
      <div className="flex flex-col gap-4">
        <div className="flex justify-between items-center">
          <span className="text-[10px] font-medium text-white/40 uppercase tracking-wider">Palette</span>
          <button onClick={onClose} className="text-white/30 hover:text-white transition-colors">
            <span className="material-symbols-outlined text-[16px]">close</span>
          </button>
        </div>

        {/* Spectrum/Custom Picker */}
        <div className="flex flex-col gap-2">
           <input 
              type="color" 
              value={color} 
              onChange={(e) => onChange(e.target.value)}
              className="w-full h-8 bg-transparent border-none p-0 cursor-pointer overflow-hidden rounded-lg"
            />
            <div className="flex items-center gap-2 px-1">
              <div className="w-4 h-4 rounded-full border border-white/20" style={{ backgroundColor: color }} />
              <span className="text-[11px] font-mono text-white/60 uppercase">{color}</span>
            </div>
        </div>

        {/* Curated Tones */}
        <div className="grid grid-cols-8 gap-1.5">
          {CURATED_TONES.map(t => (
            <button 
              key={t}
              onClick={() => { onChange(t); onClose(); }}
              className={`aspect-square rounded-md border transition-transform hover:scale-110 active:scale-95 ${color === t ? 'border-white ring-1 ring-white/20' : 'border-transparent'}`}
              style={{ backgroundColor: t }}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export const PatternEditor: React.FC<PatternEditorProps> = ({ state, onChange, onRemoveBackground, isRemovingBg }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [tool, setTool] = useState<Tool>('select');
  const [brushColor, setBrushColor] = useState(CURATED_TONES[0]);
  const [brushSize, setBrushSize] = useState(10);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);

  // History State
  const [past, setPast] = useState<{ elements: PatternElement[]; drawingBase64: string | null }[]>([]);
  const [future, setFuture] = useState<{ elements: PatternElement[]; drawingBase64: string | null }[]>([]);

  // Smoothing points buffer
  const points = useRef<{ x: number; y: number }[]>([]);
  const [startPoint, setStartPoint] = useState<{ x: number; y: number } | null>(null);

  // Expanded canvas state
  const [isExpanded, setIsExpanded] = useState(false);
  const expandedContainerRef = useRef<HTMLDivElement>(null);
  const expandedCanvasRef = useRef<HTMLCanvasElement>(null);
  const expandedPoints = useRef<{ x: number; y: number }[]>([]);
  const [expandedStartPoint, setExpandedStartPoint] = useState<{ x: number; y: number } | null>(null);

  // Initialize and persist canvas content
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d')!;
    canvas.width = 1024;
    canvas.height = 1024;

    if (state.drawingBase64) {
      const img = new Image();
      img.src = state.drawingBase64;
      img.onload = () => ctx.drawImage(img, 0, 0);
    }
  }, []);

  // Update canvas when state changes (needed for Undo/Redo)
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d')!;

    const img = new Image();
    img.src = state.drawingBase64 || 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
    img.onload = () => {
      ctx.clearRect(0, 0, 1024, 1024);
      ctx.drawImage(img, 0, 0);
    };
  }, [state.drawingBase64]);

  // Expanded canvas state sync
  useEffect(() => {
    if (!isExpanded || !expandedCanvasRef.current) return;
    const canvas = expandedCanvasRef.current;
    const ctx = canvas.getContext('2d')!;
    canvas.width = 1024;
    canvas.height = 1024;

    const img = new Image();
    img.src = state.drawingBase64 || 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
    img.onload = () => {
      ctx.clearRect(0, 0, 1024, 1024);
      ctx.drawImage(img, 0, 0);
    };
  }, [isExpanded, state.drawingBase64]);

  const pushToHistory = useCallback((currentElements: PatternElement[], currentDrawing: string | null) => {
    setPast(prev => {
      const next = [...prev, { elements: state.elements, drawingBase64: state.drawingBase64 }];
      return next.slice(-MAX_HISTORY);
    });
    setFuture([]);
  }, [state.elements, state.drawingBase64]);

  const undo = useCallback(() => {
    if (past.length === 0) return;
    const previous = past[past.length - 1];
    const newPast = past.slice(0, -1);

    setFuture(prev => [{ elements: state.elements, drawingBase64: state.drawingBase64 }, ...prev].slice(0, MAX_HISTORY));
    setPast(newPast);

    onChange({ 
      ...state, 
      elements: previous.elements, 
      drawingBase64: previous.drawingBase64 
    });
  }, [past, state, onChange]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    const newFuture = future.slice(1);

    setPast(prev => [...prev, { elements: state.elements, drawingBase64: state.drawingBase64 }].slice(-MAX_HISTORY));
    setFuture(newFuture);

    onChange({ 
      ...state, 
      elements: next.elements, 
      drawingBase64: next.drawingBase64 
    });
  }, [future, state, onChange]);

  // Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const isZ = e.key.toLowerCase() === 'z';
      const isCmdOrCtrl = e.metaKey || e.ctrlKey;
      const isShift = e.shiftKey;

      if (isCmdOrCtrl && isZ) {
        e.preventDefault();
        if (isShift) {
          redo();
        } else {
          undo();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  const saveDrawing = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const base64 = canvas.toDataURL('image/png');
    pushToHistory(state.elements, state.drawingBase64);
    onChange({ ...state, drawingBase64: base64 });
  }, [state, onChange, pushToHistory]);

  const saveExpandedDrawing = useCallback(() => {
    const canvas = expandedCanvasRef.current;
    if (!canvas) return;
    const base64 = canvas.toDataURL('image/png');
    pushToHistory(state.elements, state.drawingBase64);
    onChange({ ...state, drawingBase64: base64 });
  }, [state, onChange, pushToHistory]);

  const addShape = (type: ShapeType) => {
    pushToHistory(state.elements, state.drawingBase64);
    const newElement: PatternElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      x: 50,
      y: 50,
      size: 20,
      rotation: 0,
      color: brushColor
    };
    onChange({ ...state, elements: [...state.elements, newElement] });
    setSelectedId(newElement.id);
  };

  const updateElement = (id: string, updates: Partial<PatternElement>) => {
    onChange({
      ...state,
      elements: state.elements.map(el => el.id === id ? { ...el, ...updates } : el)
    });
  };

  const deleteElement = (id: string) => {
    pushToHistory(state.elements, state.drawingBase64);
    onChange({ ...state, elements: state.elements.filter(el => el.id !== id) });
    if (selectedId === id) setSelectedId(null);
  };

  const getCanvasPos = (e: React.MouseEvent | MouseEvent) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const scaleX = canvasRef.current.width / rect.width;
    const scaleY = canvasRef.current.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const getExpandedCanvasPos = (e: React.MouseEvent | MouseEvent) => {
    if (!expandedCanvasRef.current) return { x: 0, y: 0 };
    const rect = expandedCanvasRef.current.getBoundingClientRect();
    const scaleX = expandedCanvasRef.current.width / rect.width;
    const scaleY = expandedCanvasRef.current.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const startDrawing = (e: React.MouseEvent) => {
    if (tool === 'select') return;
    setIsDrawing(true);
    const pos = getCanvasPos(e);
    setStartPoint(pos);
    points.current = [pos];

    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;
    ctx.beginPath();
    ctx.moveTo(pos.x, pos.y);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = brushSize * 4; 
    ctx.strokeStyle = tool === 'eraser' ? '#000' : brushColor;
    ctx.globalCompositeOperation = tool === 'eraser' ? 'destination-out' : 'source-over';
  };

  const startExpandedDrawing = (e: React.MouseEvent) => {
    if (tool === 'select') return;
    setIsDrawing(true);
    const pos = getExpandedCanvasPos(e);
    setExpandedStartPoint(pos);
    expandedPoints.current = [pos];

    const ctx = expandedCanvasRef.current?.getContext('2d');
    if (!ctx) return;
    ctx.beginPath();
    ctx.moveTo(pos.x, pos.y);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = brushSize * 4; 
    ctx.strokeStyle = tool === 'eraser' ? '#000' : brushColor;
    ctx.globalCompositeOperation = tool === 'eraser' ? 'destination-out' : 'source-over';
  };

  const draw = (e: React.MouseEvent) => {
    if (!isDrawing || tool === 'select') return;
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;
    const pos = getCanvasPos(e);

    if (tool === 'brush' || tool === 'eraser') {
      points.current.push(pos);

      if (points.current.length > 2) {
        const lastTwo = points.current.slice(-3);
        const xc = (lastTwo[1].x + lastTwo[2].x) / 2;
        const yc = (lastTwo[1].y + lastTwo[2].y) / 2;
        ctx.quadraticCurveTo(lastTwo[1].x, lastTwo[1].y, xc, yc);
        ctx.stroke();
      } else {
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
      }
    }
  };

  const drawExpanded = (e: React.MouseEvent) => {
    if (!isDrawing || tool === 'select') return;
    const ctx = expandedCanvasRef.current?.getContext('2d');
    if (!ctx) return;
    const pos = getExpandedCanvasPos(e);

    if (tool === 'brush' || tool === 'eraser') {
      expandedPoints.current.push(pos);
      if (expandedPoints.current.length > 2) {
        const lastTwo = expandedPoints.current.slice(-3);
        const xc = (lastTwo[1].x + lastTwo[2].x) / 2;
        const yc = (lastTwo[1].y + lastTwo[2].y) / 2;
        ctx.quadraticCurveTo(lastTwo[1].x, lastTwo[1].y, xc, yc);
        ctx.stroke();
      } else {
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
      }
    }
  };

  const stopDrawing = (e: React.MouseEvent) => {
    if (!isDrawing) return;
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx && tool === 'line' && startPoint) {
      const pos = getCanvasPos(e);
      ctx.beginPath();
      ctx.moveTo(startPoint.x, startPoint.y);
      ctx.lineTo(pos.x, pos.y);
      ctx.stroke();
    }
    setIsDrawing(false);
    setStartPoint(null);
    points.current = [];
    saveDrawing();
  };

  const stopExpandedDrawing = (e: React.MouseEvent) => {
    if (!isDrawing) return;
    const ctx = expandedCanvasRef.current?.getContext('2d');
    if (ctx && tool === 'line' && expandedStartPoint) {
      const pos = getExpandedCanvasPos(e);
      ctx.beginPath();
      ctx.moveTo(expandedStartPoint.x, expandedStartPoint.y);
      ctx.lineTo(pos.x, pos.y);
      ctx.stroke();
    }
    setIsDrawing(false);
    setExpandedStartPoint(null);
    expandedPoints.current = [];
    saveExpandedDrawing();
  };

  const clearDrawing = () => {
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      pushToHistory(state.elements, state.drawingBase64);
      ctx.clearRect(0, 0, 1024, 1024);
      const base64 = canvasRef.current!.toDataURL('image/png');
      onChange({ ...state, drawingBase64: base64 });
    }
  };

  const handleTransform = (e: React.MouseEvent, id: string, type: 'move' | 'resize' | 'rotate') => {
    if (!containerRef.current || (tool !== 'select' && type === 'move')) return;
    e.stopPropagation();

    const rect = containerRef.current.getBoundingClientRect();
    const startX = e.clientX;
    const startY = e.clientY;
    const element = state.elements.find(el => el.id === id)!;
    const startPosX = element.x;
    const startPosY = element.y;
    const startSize = element.size;
    const startRot = element.rotation;

    const move = (moveEvent: MouseEvent) => {
      if (type === 'move') {
        const dx = ((moveEvent.clientX - startX) / rect.width) * 100;
        const dy = ((moveEvent.clientY - startY) / rect.height) * 100;
        updateElement(id, { 
          x: Math.max(0, Math.min(100, startPosX + dx)), 
          y: Math.max(0, Math.min(100, startPosY + dy)) 
        });
      } else if (type === 'resize') {
        const dx = moveEvent.clientX - startX;
        const dy = moveEvent.clientY - startY;
        const dist = Math.sqrt(dx * dx + dy * dy) * (dx + dy > 0 ? 1 : -1);
        const sizeDelta = (dist / rect.width) * 100;
        updateElement(id, { size: Math.max(5, Math.min(80, startSize + sizeDelta)) });
      } else if (type === 'rotate') {
        const centerX = rect.left + (element.x / 100) * rect.width;
        const centerY = rect.top + (element.y / 100) * rect.height;
        const angle = Math.atan2(moveEvent.clientY - centerY, moveEvent.clientX - centerX) * (180 / Math.PI);
        updateElement(id, { rotation: (angle + 90) % 360 });
      }
    };

    const stop = () => {
      window.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', stop);
      document.body.style.cursor = '';

      const currentEl = state.elements.find(el => el.id === id);
      if (currentEl && (currentEl.x !== startPosX || currentEl.y !== startPosY || currentEl.size !== startSize || currentEl.rotation !== startRot)) {
        setPast(prev => {
          const prevState = { 
            elements: state.elements.map(el => el.id === id ? { ...el, x: startPosX, y: startPosY, size: startSize, rotation: startRot } : el),
            drawingBase64: state.drawingBase64 
          };
          const next = [...prev, prevState];
          return next.slice(-MAX_HISTORY);
        });
        setFuture([]);
      }
    };

    document.body.style.cursor = type === 'move' ? 'move' : type === 'resize' ? 'nwse-resize' : 'sync';
    window.addEventListener('mousemove', move);
    window.addEventListener('mouseup', stop);
  };

  const handleExpandedTransform = (e: React.MouseEvent, id: string, type: 'move' | 'resize' | 'rotate') => {
    if (!expandedContainerRef.current || (tool !== 'select' && type === 'move')) return;
    e.stopPropagation();

    const rect = expandedContainerRef.current.getBoundingClientRect();
    const startX = e.clientX;
    const startY = e.clientY;
    const element = state.elements.find(el => el.id === id)!;
    const startPosX = element.x;
    const startPosY = element.y;
    const startSize = element.size;
    const startRot = element.rotation;

    const move = (moveEvent: MouseEvent) => {
      if (type === 'move') {
        const dx = ((moveEvent.clientX - startX) / rect.width) * 100;
        const dy = ((moveEvent.clientY - startY) / rect.height) * 100;
        updateElement(id, { 
          x: Math.max(0, Math.min(100, startPosX + dx)), 
          y: Math.max(0, Math.min(100, startPosY + dy)) 
        });
      } else if (type === 'resize') {
        const dx = moveEvent.clientX - startX;
        const dy = moveEvent.clientY - startY;
        const dist = Math.sqrt(dx * dx + dy * dy) * (dx + dy > 0 ? 1 : -1);
        const sizeDelta = (dist / rect.width) * 100;
        updateElement(id, { size: Math.max(5, Math.min(80, startSize + sizeDelta)) });
      } else if (type === 'rotate') {
        const centerX = rect.left + (element.x / 100) * rect.width;
        const centerY = rect.top + (element.y / 100) * rect.height;
        const angle = Math.atan2(moveEvent.clientY - centerY, moveEvent.clientX - centerX) * (180 / Math.PI);
        updateElement(id, { rotation: (angle + 90) % 360 });
      }
    };

    const stop = () => {
      window.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', stop);
      document.body.style.cursor = '';

      const currentEl = state.elements.find(el => el.id === id);
      if (currentEl && (currentEl.x !== startPosX || currentEl.y !== startPosY || currentEl.size !== startSize || currentEl.rotation !== startRot)) {
        setPast(prev => {
          const prevState = { 
            elements: state.elements.map(el => el.id === id ? { ...el, x: startPosX, y: startPosY, size: startSize, rotation: startRot } : el),
            drawingBase64: state.drawingBase64 
          };
          const next = [...prev, prevState];
          return next.slice(-MAX_HISTORY);
        });
        setFuture([]);
      }
    };

    document.body.style.cursor = type === 'move' ? 'move' : type === 'resize' ? 'nwse-resize' : 'sync';
    window.addEventListener('mousemove', move);
    window.addEventListener('mouseup', stop);
  };

  return (
    <>
      <div className="flex flex-col gap-6">
        <div className="flex flex-col gap-3">
          <div className="flex justify-between items-center px-1">
            <SectionLabel>Collage Canvas</SectionLabel>
            <button onClick={clearDrawing} className="text-[10px] uppercase tracking-wider text-white/30 hover:text-white transition-colors">Clear Strokes</button>
          </div>
          <div 
            ref={containerRef}
            className={`relative aspect-square w-full bg-[#1a1a1a] border border-white/10 rounded-2xl overflow-hidden ${tool === 'select' ? 'cursor-default' : 'cursor-none'}`}
            onMouseDown={(e) => {
              if (tool === 'select') {
                setSelectedId(null);
              } else {
                startDrawing(e);
              }
            }}
            onMouseMove={draw}
            onMouseUp={stopDrawing}
            onMouseLeave={stopDrawing}
          >
            <button 
              onClick={(e) => { e.stopPropagation(); setIsExpanded(true); }}
              className="absolute top-3 right-3 z-[60] w-8 h-8 rounded-lg bg-black/40 hover:bg-black/60 border border-white/10 flex items-center justify-center text-white/40 hover:text-white transition-all shadow-lg"
              title="Expand Canvas"
            >
              <span className="material-symbols-outlined text-[18px]">open_in_full</span>
            </button>

            {state.background && (
              <img 
                src={`data:${state.background.mimeType};base64,${state.background.base64}`}
                className="absolute inset-0 w-full h-full object-contain pointer-events-none opacity-50"
                alt="Background"
              />
            )}

            <canvas 
              ref={canvasRef}
              className="absolute inset-0 w-full h-full pointer-events-none"
            />

            {tool !== 'select' && isDrawing && (
              <div className="absolute w-1 h-1 bg-white rounded-full pointer-events-none mix-blend-difference" />
            )}

            {state.elements.map((el) => (
              <div
                key={el.id}
                onMouseDown={(e) => {
                  e.stopPropagation();
                  setSelectedId(el.id);
                  if (tool === 'select') {
                    handleTransform(e, el.id, 'move');
                  } else {
                    startDrawing(e);
                  }
                }}
                style={{
                  left: `${el.x}%`,
                  top: `${el.y}%`,
                  width: `${el.size}%`,
                  height: `${el.size}%`,
                  transform: `translate(-50%, -50%) rotate(${el.rotation}deg)`,
                  borderColor: selectedId === el.id ? '#ffffff' : 'transparent',
                  zIndex: selectedId === el.id ? 20 : 10
                }}
                className={`absolute border transition-colors flex items-center justify-center cursor-move group ${selectedId === el.id ? 'ring-1 ring-white/20' : ''}`}
              >
                {el.type === 'circle' && <div className="w-full h-full rounded-full border" style={{ backgroundColor: `${el.color}33`, borderColor: el.color }} />}
                {el.type === 'square' && <div className="w-full h-full border" style={{ backgroundColor: `${el.color}33`, borderColor: el.color }} />}
                {el.type === 'triangle' && (
                  <div 
                    className="w-full h-full border"
                    style={{ backgroundColor: `${el.color}33`, borderColor: el.color, clipPath: 'polygon(50% 0%, 0% 100%, 100% 100%)' }}
                  />
                )}
                {el.type === 'line' && <div className="w-full h-1" style={{ backgroundColor: el.color }} />}

                {selectedId === el.id && (
                  <>
                    <div 
                      className="absolute -top-8 left-1/2 -translate-x-1/2 w-4 h-4 bg-white rounded-full border border-black/20 flex items-center justify-center cursor-pointer shadow-lg"
                      onMouseDown={(e) => handleTransform(e, el.id, 'rotate')}
                    >
                      <span className="material-symbols-outlined text-[10px] text-black">sync</span>
                    </div>
                    <div 
                      className="absolute -bottom-1 -right-1 w-3 h-3 bg-white border border-black/20 cursor-nwse-resize shadow-lg"
                      onMouseDown={(e) => handleTransform(e, el.id, 'resize')}
                    />
                    <button 
                      className="absolute -top-3 -right-3 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center shadow-lg transition-transform hover:scale-110 active:scale-95"
                      onMouseDown={(e) => { e.stopPropagation(); deleteElement(el.id); }}
                    >
                      <span className="material-symbols-outlined text-[12px] text-white">close</span>
                    </button>
                  </>
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <div className="flex justify-between items-center px-1">
            <SectionLabel>Drafting Tools</SectionLabel>
            <div className="flex gap-2">
              <button 
                onClick={undo} 
                disabled={past.length === 0}
                className="text-white/30 hover:text-white disabled:opacity-10 transition-colors flex items-center gap-1"
              >
                <span className="material-symbols-outlined text-[18px]">undo</span>
              </button>
              <button 
                onClick={redo} 
                disabled={future.length === 0}
                className="text-white/30 hover:text-white disabled:opacity-10 transition-colors flex items-center gap-1"
              >
                <span className="material-symbols-outlined text-[18px]">redo</span>
              </button>
            </div>
          </div>

          <div className="flex flex-col gap-3 p-3 bg-white/5 rounded-xl">
            <div className="flex gap-1 justify-between relative">
              <div className="flex gap-1">
                {(['select', 'brush', 'line', 'eraser'] as Tool[]).map(t => (
                  <button 
                    key={t}
                    onClick={() => { setTool(t); }}
                    className={`w-9 h-9 rounded-lg flex items-center justify-center transition-all ${tool === t ? 'bg-white text-black' : 'bg-white/5 hover:bg-white/10 text-white/60'}`}
                  >
