              ref={expandedContainerRef}
              className={`relative h-full aspect-square bg-[#1a1a1a] border border-white/10 rounded-3xl shadow-[0_32px_64px_-12px_rgba(0,0,0,0.8)] overflow-hidden ${tool === 'select' ? 'cursor-default' : 'cursor-none'} animate-in zoom-in-95 duration-700`}
              onMouseDown={(e) => {
                if (tool === 'select') {
                  setSelectedId(null);
                } else {
