                }
              }}
              onMouseMove={drawExpanded}
              onMouseUp={stopExpandedDrawing}
              onMouseLeave={stopExpandedDrawing}
            >
              {state.background && (
                <img 
                  src={`data:${state.background.mimeType};base64,${state.background.base64}`}
                  className="absolute inset-0 w-full h-full object-contain pointer-events-none opacity-50"
