                <div className="absolute w-1.5 h-1.5 bg-white rounded-full pointer-events-none mix-blend-difference" />
              )}

              {state.elements.map((el) => (
                <div
                  key={el.id}
                  onMouseDown={(e) => {
                    e.stopPropagation();
                    setSelectedId(el.id);
                    if (tool === 'select') {
