                    } else {
                      startExpandedDrawing(e);
                    }
                  }}
                  style={{
                    left: `${el.x}%`,
                    top: `${el.y}%`,
                    width: `${el.size}%`,
                    height: `${el.size}%`,
                    transform: `translate(-50%, -50%) rotate(${el.rotation}deg)`,
                    borderColor: selectedId === el.id ? '#ffffff' : 'transparent',
                    zIndex: selectedId === el.id ? 20 : 10
                  }}
                  className={`absolute border transition-colors flex items-center justify-center cursor-move group ${selectedId === el.id ? 'ring-1 ring-white/20' : ''}`}
                >
                  {el.type === 'circle' && <div className="w-full h-full rounded-full border" style={{ backgroundColor: `${el.color}33`, borderColor: el.color }} />}
                  {el.type === 'square' && <div className="w-full h-full border" style={{ backgroundColor: `${el.color}33`, borderColor: el.color }} />}
                  {el.type === 'triangle' && (
                    <div 
                      className="w-full h-full border"
                      style={{ backgroundColor: `${el.color}33`, borderColor: el.color, clipPath: 'polygon(50% 0%, 0% 100%, 100% 100%)' }}
                    />
                  )}
                  {el.type === 'line' && <div className="w-full h-1" style={{ backgroundColor: el.color }} />}

                  {selectedId === el.id && (
                    <>
                      <div 
                        className="absolute -top-10 left-1/2 -translate-x-1/2 w-6 h-6 bg-white rounded-full border border-black/20 flex items-center justify-center cursor-pointer shadow-lg"
                        onMouseDown={(e) => handleExpandedTransform(e, el.id, 'rotate')}
                      >
                        <span className="material-symbols-outlined text-[14px] text-black">sync</span>
                      </div>
                      <div 
                        className="absolute -bottom-2 -right-2 w-4 h-4 bg-white border border-black/20 cursor-nwse-resize shadow-lg"
                        onMouseDown={(e) => handleExpandedTransform(e, el.id, 'resize')}
                      />
                      <button 
                        className="absolute -top-4 -right-4 w-7 h-7 bg-red-500 rounded-full flex items-center justify-center shadow-lg transition-transform hover:scale-110 active:scale-95"
                        onMouseDown={(e) => { e.stopPropagation(); deleteElement(el.id); }}
                      >
                        <span className="material-symbols-outlined text-[16px] text-white">close</span>
                      </button>
                    </>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
