}

const LIGHTING_OPTIONS = ['Natural Daylight', 'Golden Hour', 'Moody Studio', 'Soft Dusk'];
const STYLE_OPTIONS = ['Modern', 'Art Deco', 'Botanical', 'Geometric'];

export function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => { document.removeEventListener('mousedown', listener); document.removeEventListener('touchstart', listener); };
  }, [ref, handler]);
}

