import React, { useState, useMemo, useRef, useEffect } from 'react';
import { MaterialAsset, GenerationState, AppMode } from '../types';

interface CopilotHelperProps {
  mode: AppMode;
  prompt: string;
  inputImage: any;
  tile: MaterialAsset | null;
  stagedImage: MaterialAsset | null;
  sceneImage: MaterialAsset | null;
  view: 'tile' | 'staged' | 'scene';
  status: GenerationState;
  isWelcomeDone: boolean;
}

/**
 * Custom hook to handle clicks outside the popover
 */
function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: () => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler();
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => {
      document.removeEventListener('mousedown', listener);
      document.removeEventListener('touchstart', listener);
    };
  }, [ref, handler]);
}

export const CopilotHelper: React.FC<CopilotHelperProps> = ({
  mode,
  prompt,
  inputImage,
  tile,
  stagedImage,
  sceneImage,
  view,
  status,
  isWelcomeDone
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const lastPrompt = useRef<string>(prompt);
  const hasShownPatternHelp = useRef<boolean>(false);
  const hasShownMaterialHelp = useRef<boolean>(false);

  useOnClickOutside(containerRef, () => setIsOpen(false));

  // Determine the guidance message based on mode, state and status
  const message = useMemo(() => {
    // Priority 1: Active Generation Statuses
    if (status !== 'idle') {
      switch (status) {
        case 'generating_tile': return "Crafting your material tile. This usually takes about 30 seconds.";
        case 'staging': return "Placing your material in situ... Generating architectural render.";
        case 'removing_bg': return "Removing background and isolating pattern elements.";
        case 'blending_pattern': return "Synthesizing your sketch and elements into a refined material.";
        case 'healing_seams': return "Remastering the edges to ensure perfect tiling.";
        default: return "Processing your request...";
      }
    }

    // Priority 2: Mode-specific guidance
    if (mode === 'pattern') {
      return "Welcome to Pattern Mode. Upload an image to isolate elements, or use the Collage Canvas to draft shapes and strokes. Adjust the Repeat Layout to see it tile.";
    }

    // Priority 3: Result-based guidance (Material Mode)
    const hasInput = prompt.trim().length > 0 || !!inputImage;
    const hasStaged = !!stagedImage && view === 'staged';
    const hasScene = !!sceneImage && view === 'scene';

    if (hasStaged || hasScene) {
      return "Refine your scene, or export your Tile or Preview when ready.";
    }
    if (tile) {
      return "Your tile is ready. Choose Floor, Wall or Ceiling, then See it in a space.";
    }
    if (hasInput) {
      return "Now press Generate Tile — or Add Reference to guide it with an image.";
    }
    return "Welcome to Surface. Describe a material on the left, or pick one to begin.";
  }, [mode, prompt, inputImage, tile, stagedImage, sceneImage, view, status]);

  // Auto-open logic for prompt changes
  useEffect(() => {
    const isNewPrompt = prompt !== lastPrompt.current;
    if (status === 'idle' && isNewPrompt && prompt.trim().length > 0 && isWelcomeDone && mode === 'material') {
      setIsOpen(true);
    }
    lastPrompt.current = prompt;
  }, [prompt, status, isWelcomeDone, mode]);

  // Auto-open logic for first-time pattern mode entry
  useEffect(() => {
    if (mode === 'pattern' && !hasShownPatternHelp.current && isWelcomeDone) {
      setIsOpen(true);
      hasShownPatternHelp.current = true;
    }
  }, [mode, isWelcomeDone]);

  // Auto-open logic for first-time material mode entry (initial state)
  useEffect(() => {
    if (isWelcomeDone && !hasShownMaterialHelp.current && mode === 'material') {
      setIsOpen(true);
      hasShownMaterialHelp.current = true;
    }
  }, [isWelcomeDone, mode]);

  return (
    <div 
      ref={containerRef}
      className="fixed top-4 right-4 z-[70] flex flex-col items-end pointer-events-none"
    >
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`
          pointer-events-auto
          flex items-center justify-center w-10 h-10 rounded-full
          bg-black/60 backdrop-blur-xl border border-white/10
          text-white/40 hover:text-white transition-all shadow-2xl
          ${isOpen ? 'bg-white/10 text-white border-white/20' : ''}
        `}
      >
        <span className="material-symbols-outlined text-[18px]">
          {isOpen ? 'close' : 'magic_button'}
        </span>
      </button>

      {isOpen && (
        <div 
          className="
            absolute top-12 right-0 pointer-events-auto
            w-64 p-4 bg-black/80 backdrop-blur-3xl rounded-2xl
            shadow-[0_20px_50px_rgba(0,0,0,0.6)] animate-in fade-in zoom-in-95 duration-200 origin-top-right
          "
          style={{ border: '1px solid #9C7A4A' }}
        >
          <div className="flex flex-col gap-3">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-1.5 opacity-30">
                <span className="material-symbols-outlined text-[14px]">auto_awesome</span>
                <span className="text-[9px] uppercase tracking-widest font-medium">Assistant</span>
              </div>
              <button 
                onClick={() => setIsOpen(false)}
                className="text-white/20 hover:text-white transition-colors"
              >
                <span className="material-symbols-outlined text-[14px]">close</span>
              </button>
            </div>

            <div className="space-y-3">
              <p className="text-[11px] text-white/70 font-light leading-relaxed tracking-tight">
                {message}
              </p>

              <div className="pt-2 border-t border-white/5">
                <p className="text-[9px] text-[#9C7A4A] opacity-80 leading-tight font-medium">
                  Note: You can click this icon any time you need help on the next step!
                </p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
